/**
 * Spanish locale (es) - implemented in 4.6.0 from docs/locales/es-SPEC.md
 * (RAE sources quoted there). Distinctive: the irregular hundreds chain
 * (quinientos/seiscientos/setecientos/ochocientos/novecientos), the cien vs
 * ciento split, the veinti- contractions with RAE apocope before mil
 * ("veintiún mil"), and the long-scale million family ("mil millones",
 * "billón" = 10^12).
 *
 * Words for 0..99 are GENERATED by the rules below. Masculine forms are used
 * throughout (no gender context in the engine - SPEC §1). Ordinals reject
 * loudly (periphrastic preference, SPEC §6); decimal ordinals are localized
 * via `decimalOrdinal`; currency mode works.
 */

import { illionName } from "../illions.js";
import { wholePartToWords } from "../words.js";
import type { LocaleDefinition } from "./types.js";

const UNITS = [
  "uno",
  "dos",
  "tres",
  "cuatro",
  "cinco",
  "seis",
  "siete",
  "ocho",
  "nueve",
] as const;

const TEENS = [
  "once",
  "doce",
  "trece",
  "catorce",
  "quince",
  "dieciséis",
  "diecisiete",
  "dieciocho",
  "diecinueve",
] as const;

const TENS = [
  "treinta",
  "cuarenta",
  "cincuenta",
  "sesenta",
  "setenta",
  "ochenta",
  "noventa",
] as const;

/** Irregular hundreds 200-900 (100/101 handled by hundredPhraseFor). */
const HUNDREDS = [
  "doscientos",
  "trescientos",
  "cuatrocientos",
  "quinientos",
  "seiscientos",
  "setecientos",
  "ochocientos",
  "novecientos",
] as const;

/** Spanish illion series for even group indexes (SPEC §5). */
const ILLIONS = [
  "millón",
  "billón",
  "trillón",
  "cuatrillón",
  "quintillón",
  "sextillón",
  "septillón",
  "octillón",
  "nonillón",
  "decillón",
] as const;

/** Builds the 0..99 word table from the verified rules (SPEC §2). */
function buildSmallNumbers(): string[] {
  const table: string[] = [];

  table[0] = "cero";
  UNITS.forEach((word, index) => {
    table[index + 1] = word;
  });

  table[10] = "diez";
  TEENS.forEach((word, index) => {
    table[11 + index] = word;
  });

  table[20] = "veinte";
  table[21] = "veintiuno";
  table[22] = "veintidós";
  table[23] = "veintitrés";
  table[24] = "veinticuatro";
  table[25] = "veinticinco";
  table[26] = "veintiséis";
  table[27] = "veintisiete";
  table[28] = "veintiocho";
  table[29] = "veintinueve";

  TENS.forEach((stem, tensIndex) => {
    const base = 30 + tensIndex * 10;
    table[base] = stem;
    UNITS.forEach((word, index) => {
      table[base + 1 + index] = `${stem} y ${word}`; // treinta y uno ...
    });
  });

  return table;
}

const ES_SMALL_NUMBERS: string[] = buildSmallNumbers();

/**
 * RAE apocope for multipliers before mil: veintiuno -> veintiún,
 * (treinta y) uno -> (treinta y) un; multipliers >= 100 use the rendered
 * group words ("cien mil", "ciento un mil", "doscientos treinta y cuatro mil").
 */
function esMultiplier(value: number, groupWords: string): string {
  if (value === 21) {
    return "veintiún";
  }
  if (value % 10 === 1 && value !== 11) {
    return groupWords.replace(/uno$/, "un");
  }
  return groupWords;
}

/** Spanish long-scale illion family (SPEC §5): even group indexes. */
function esIllion(groupIndex: number): string {
  const half = groupIndex / 2; // groupIndex 2 -> millón, 4 -> billón ...
  if (Number.isInteger(half) && half >= 1 && half <= ILLIONS.length) {
    return ILLIONS[half - 1] as string;
  }
  return illionName(groupIndex - 1).toLowerCase(); // documented code-switch
}

/** Pluralizes a Spanish illion: millón -> millones, billón -> billones. */
function pluralIllion(name: string): string {
  return name.replace(/ón$/, "ones");
}

/** Scale composition (SPEC §5): the hook owns the whole group phrase. */
function esScaleWord(groupIndex: number, groupValue: number, groupWords: string): string {
  if (groupIndex % 2 === 0) {
    // Even: 10^(3i) = one of the illion series, group-first ("dos billones").
    const name = esIllion(groupIndex);
    return groupValue === 1 ? `un ${name}` : `${groupWords} ${pluralIllion(name)}`;
  }
  // Odd (>= 3): "mil" + the previous illion in plural ("mil millones",
  // "cinco mil billones"), group-first as well.
  const previous = esIllion(groupIndex - 1);
  const phrase = `mil ${pluralIllion(previous)}`;
  return groupValue === 1 ? phrase : `${groupWords} ${phrase}`;
}

/** Decimal ordinals per the RAE scale (SPEC §6). */
function esDecimalOrdinal(place: number, singular: boolean): string {
  let word: string;
  if (place === 1) {
    word = "décima";
  } else if (place === 2) {
    word = "centésima";
  } else {
    const remainder = place % 3;
    const q = (place - remainder) / 3;
    let scale: string;
    if (q === 1) {
      scale = "milésima";
    } else if (q % 2 === 0) {
      scale = pluralIllionToOrdinal(esIllion(q));
    } else {
      scale = `mil${pluralIllionToOrdinal(esIllion(q - 1))}`;
    }
    const prefix = remainder === 1 ? "diez" : remainder === 2 ? "cien" : "";
    word = `${prefix}${scale}`;
  }
  return singular ? word : `${word}s`;
}

function pluralIllionToOrdinal(name: string): string {
  return `${name.replace(/ón$/, "on")}ésima`;
}

/**
 * Feminine agreement for decimal fractions (décimas/centésimas are feminine):
 * "una décima", "veintiuna centésimas", "doscientas milésimas".
 */
function esDecimalDigitWord(digits: string): string {
  const value = BigInt(digits);
  if (value === 0n) {
    return "cero";
  }
  let word = wholePartToWords(digits, esLocale, "american");
  if (value % 100n === 0n && value >= 200n) {
    word = word.replace("cientos", "cientas");
  }
  if (value % 10n === 1n && value % 100n !== 11n) {
    word = word.replace(/uno$/, "una");
  }
  return word;
}

export const esLocale: LocaleDefinition = {
  code: "es",
  zeroWord: "cero",
  smallNumbers: ES_SMALL_NUMBERS,
  hundredWord: "ciento",
  thousandWord: "mil",
  negativePrefix: "(negativo) ",
  dotSeparator: " (punto) ",
  andStyle: "american", // the "y" lives inside the 0..99 words; no outer joiner
  supportsBothStyles: false,
  groupSeparator: " ",
  scaleWordFor: esScaleWord,
  thousandPhraseFor: (groupValue, groupWords) =>
    groupValue === 1 ? "mil" : `${esMultiplier(groupValue, groupWords)} mil`,
  hundredPhraseFor: (hundreds, remainder) =>
    hundreds === 1 ? (remainder === 0 ? "cien" : "ciento") : (HUNDREDS[hundreds - 2] as string),
  decimalOrdinal: esDecimalOrdinal,
  decimalDigitWord: esDecimalDigitWord,
};
